function chili(t,s=1,o={}){const col=o.col||'#E5383B';return g(`scale(${s}) rotate(${o.r||0})`,`<path d="M-40,-150C-20,-170 20,-170 30,-140C70,-40 60,80 -10,170C-30,190 -40,180 -30,150C0,60 -20,-40 -60,-120C-70,-140 -60,-150 -40,-150Z" fill="${col}" stroke="${OL}" stroke-width="7" stroke-linejoin="round"/><path d="M-10,-150C-20,-190 10,-210 40,-200" stroke="#3BB273" stroke-width="16" fill="none" stroke-linecap="round"/><path d="M-40,-150Q-10,-175 30,-145Q0,-125 -40,-150Z" fill="#3BB273" stroke="${OL}" stroke-width="5"/><path d="M-30,-100Q-10,0 -20,90" stroke="#fff" stroke-width="12" fill="none" opacity=".45" stroke-linecap="round"/>${o.face!==false?`<circle cx="-4" cy="-40" r="9" fill="#2E2430"/><circle cx="34" cy="-36" r="9" fill="#2E2430"/><path d="M0,0Q16,${o.sad?-10:14} 32,0" stroke="#2E2430" stroke-width="6" fill="none" stroke-linecap="round"/>`:''}`);}
