function seq(t,items){let s='';for(const it of items){if(it.a==null||t<it.a)continue;if(it.u!=null&&t>=it.u)continue;s+=popAt(t,it.a,it.f(t),it.x,it.y,it.s||1,it.r||0);}return s;}
