function star7(r){let p='';for(let i=0;i<14;i++){const a=-Math.PI/2+i*Math.PI/7,rr=i%2?r*0.45:r;p+=(i?'L':'M')+fmt(rr*Math.cos(a))+','+fmt(rr*Math.sin(a));}return `<path d="${p}Z" fill="#fff"/>`;}
